import{Z as i,e as n,f as t,a0 as a}from"./chunks/framework.DmpHOl9T.js";const g=JSON.parse('{"title":"Re-Run Failed Integrations from the Control Panel","description":"","frontmatter":{},"headers":[],"relativePath":"guides/integrations/re-run-failed-integrations-from-the-control-panel.md","filePath":"guides/integrations/re-run-failed-integrations-from-the-control-panel.md","lastUpdated":1782532814000}'),s={name:"guides/integrations/re-run-failed-integrations-from-the-control-panel.md"};function r(o,e,l,h,d,u){return n(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="re-run-failed-integrations-from-the-control-panel" tabindex="-1">Re-Run Failed Integrations from the Control Panel <a class="header-anchor" href="#re-run-failed-integrations-from-the-control-panel" aria-label="Permalink to &quot;Re-Run Failed Integrations from the Control Panel&quot;">​</a></h1><p>Integrations can fail when a provider is down, credentials expire, or mapping sends invalid data. Formie lets operators manually re-trigger an integration for an existing submission from the control panel — without resubmitting the form or writing custom code.</p><p>This guide covers manual re-runs from the submission edit screen. For email delivery failures, use <a href="/forms/sent-notifications">Sent Notifications</a> to inspect and resend notification messages separately.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A saved submission with at least one enabled payload integration on its form</li><li>Permission to edit submissions in the control panel</li></ul><h2 id="when-to-re-run-manually" tabindex="-1">When to Re-Run Manually <a class="header-anchor" href="#when-to-re-run-manually" aria-label="Permalink to &quot;When to Re-Run Manually&quot;">​</a></h2><p>Manual re-runs help when:</p><ul><li>A queue job failed and the provider never received the data</li><li>Credentials were fixed after submissions already failed</li><li>Mapping was corrected and you need to push updated submission values</li><li>A transient API error occurred and a retry should succeed</li></ul><p>Manual re-runs are <strong>not</strong> a substitute for fixing systemic problems. If every submission fails, check integration credentials, mapping, provider status, and Craft queue logs first.</p><p>Enable <strong>Send Email Alert for Failed Integration</strong> under <strong>Formie → Settings → Integrations</strong> so your team is notified when failures happen automatically — you may not need to discover them by checking each submission.</p><h2 id="re-run-from-the-submission-edit-screen" tabindex="-1">Re-Run from the Submission Edit Screen <a class="header-anchor" href="#re-run-from-the-submission-edit-screen" aria-label="Permalink to &quot;Re-Run from the Submission Edit Screen&quot;">​</a></h2><ol><li>Go to <strong>Formie → Submissions</strong> and open the submission.</li><li>In the sidebar, find the <strong>Integrations</strong> dropdown (visible when the form has enabled payload integrations and the submission is not spam or incomplete).</li><li>Select the integration you want to run.</li><li>Confirm the prompt — <strong>Are you sure you want to trigger the {name} integration?</strong></li><li>Wait for the page to reload. A success or error flash message appears.</li></ol><p>The re-run uses the submission’s current field values and the form’s current integration settings. If you edited the submission or changed mapping since the original dispatch, the new values and settings apply.</p><h3 id="what-manual-re-runs-respect" tabindex="-1">What Manual Re-Runs Respect <a class="header-anchor" href="#what-manual-re-runs-respect" aria-label="Permalink to &quot;What Manual Re-Runs Respect&quot;">​</a></h3><p>A manual re-run uses the saved integration settings and the submission’s current answers. It runs the integration’s normal delivery path, so its mapping, events and logging apply.</p><p>Manual re-runs <strong>still evaluate integration conditions</strong>. If conditions fail for the submission, the integration will not send data even when triggered manually.</p><p>Manual re-runs bypass re-run <strong>policy</strong> checks — policies govern automatic triggers on edit or resubmit, not operator-initiated runs.</p><h3 id="what-is-not-re-run" tabindex="-1">What Is Not Re-Run <a class="header-anchor" href="#what-is-not-re-run" aria-label="Permalink to &quot;What Is Not Re-Run&quot;">​</a></h3><p>Manual integration re-runs do not:</p><ul><li>Resend email notifications (use Sent Notifications for that)</li><li>Re-validate or re-save the submission</li><li>Re-run captcha or spam screening</li><li>Trigger other integrations unless you run each one separately</li></ul><h2 id="re-run-from-the-command-line" tabindex="-1">Re-Run from the Command Line <a class="header-anchor" href="#re-run-from-the-command-line" aria-label="Permalink to &quot;Re-Run from the Command Line&quot;">​</a></h2><p>For bulk recovery or automation, use the Formie console command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> formie/submissions/run-integration</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --submission-id=123</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --integration=mailchimp</span></span></code></pre></div><p>Pass comma-separated submission IDs to process multiple submissions:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> formie/submissions/run-integration</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --submission-id=123,124,125</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --integration=mailchimp</span></span></code></pre></div><p>The handle matches the integration handle in <strong>Formie → Integrations</strong>.</p><h2 id="troubleshooting-failed-integrations" tabindex="-1">Troubleshooting Failed Integrations <a class="header-anchor" href="#troubleshooting-failed-integrations" aria-label="Permalink to &quot;Troubleshooting Failed Integrations&quot;">​</a></h2><p>When a re-run fails:</p><ol><li>Check <strong>Craft → Utilities → Logs</strong> for Formie integration errors.</li><li>Open the failed queue job under <strong>Utilities → Queue Manager</strong> if the original run was queued — payload details are included for debugging.</li><li>Verify credentials under <strong>Formie → Integrations</strong> — reconnect OAuth integrations if tokens expired.</li><li>Confirm mapping on the form’s Integrations tab matches what the provider expects.</li><li>Test with a fresh front-end submission after fixing the root cause.</li></ol><p>For dispatch order issues — for example, an automation running before a User integration creates an account — see <a href="/guides/integrations/integration-dispatch-and-policies">Integration dispatch and policies</a>.</p><h2 id="sent-notifications-vs-integration-re-runs" tabindex="-1">Sent Notifications vs Integration Re-Runs <a class="header-anchor" href="#sent-notifications-vs-integration-re-runs" aria-label="Permalink to &quot;Sent Notifications vs Integration Re-Runs&quot;">​</a></h2><p>These solve different problems:</p><table tabindex="0"><thead><tr><th>Problem</th><th>Tool</th></tr></thead><tbody><tr><td>CRM / automation / marketing API did not receive data</td><td>Submission sidebar <strong>Integrations</strong> menu or console command</td></tr><tr><td>Email notification was not sent or needs resending</td><td><strong>Formie → Sent Notifications</strong></td></tr></tbody></table><p>A submission can succeed while an individual integration fails, or vice versa. Check the appropriate log or screen for the failure type you are investigating.</p>`,34)])])}const c=i(s,[["render",r]]);export{g as __pageData,c as default};
